const app=document.querySelector('#app'), dialog=document.querySelector('#dialog');
let data=load(),slot=0,screen='title',game=null,pointer=null,last=performance.now(),toastTimer,pendingDelete=null;
const soundtrack=new Soundtrack(data.settings.sound);
// Warm the clear illustration so the first fanfare and pose arrive together.
new Image().src='./assets/luka-victory.webp';
const rankings=new RankingClient({onChange:run=>{document.querySelectorAll('[data-rank-run]').forEach(el=>{if(el.dataset.rankRun===run.runId)el.textContent=rankStatus(run);});}});
window.addEventListener('online',()=>void rankings.flush());void rankings.flush();
let rankingStarting=false,pendingScene=null;
// A visitor from a share page is counted once, when they create their first workshop.
let arrivedViaShare=null;try{const params=new URL(location.href).searchParams;if(params.get('via')==='share'){arrivedViaShare=params.get('kind')||'title';history.replaceState(null,'',location.pathname);}}catch{}
const $=s=>document.querySelector(s);
const button=(text,action,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){if(!save(data))toast('このブラウザでは保存できません。通常のブラウザで開いてね。');}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function modal(title,body,actions){soundtrack.duck('dialog',true);pendingDelete=null;if(game)game.paused=true;pointer=null;dialog.innerHTML=`<div class="dialog-inner"><p class="eyebrow">MIRACLE MINE</p><h2>${title}</h2>${body}<div class="dialog-actions">${actions}</div></div>`;dialog.classList.toggle('victory-dialog',!!dialog.querySelector('.victory-effects'));if(!dialog.open)dialog.showModal();}
function closeModal(resume=true){soundtrack.duck('dialog',false);pendingDelete=null;dialog.close();if(game&&resume&&!game.over)game.paused=false;last=performance.now();}
function chrome(title,back='title'){return `<header>${button('‹ 戻る',back,'subtle')}<div><small>MIRACLE MINE</small><h2>${title}</h2></div>${button(menuIcon(4)+'設定','settings','subtle')}</header>`;}
function setScreen(name){if(name!=='game')soundtrack.duck('result',false);soundtrack.setScene(name==='game'?gameMusicScene(game.mode,game.stage.chapter):name);screen=name;document.body.dataset.screen=name;document.body.dataset.chapter=game?.stage.chapter??0;}
const menuIcon=n=>`<i class="menu-art" aria-hidden="true" style="--icon-x:${n%3*50}%;--icon-y:${Math.floor(n/3)*100}%"></i>`;
function title(){game=null;closeModal(false);setScreen('title');app.innerHTML=`<section class="title-screen illustrated-title">${button('音楽を再生','music-toggle','title-audio subtle')}<div class="title-copy"><div class="title-masthead"><p class="eyebrow">数字がつながる、せかいがひろがる</p><h1 class="title-logo"><img src="/assets/title-logo.webp" alt="Miracle Mine" width="1536" height="1024" fetchpriority="high"></h1><p class="kana">ミラクルマイン</p></div><div class="title-portrait-scene" role="img" aria-label="ルカとトトじい、モスが蒸気飛行機と一緒に冒険へ出発する工房"></div><nav class="main-menu" aria-label="ゲームモード">${button(menuIcon(0)+(data.slots.some(Boolean)?'冒険をつづける':'冒険をはじめる'),'slots')}</nav></div><div class="title-bottom"><p class="title-tag">小さな数字で、大きな冒険へ。</p>${button(menuIcon(3)+'あそびかた','help','subtle')}${button(menuIcon(5)+'ホーム画面に追加','install','subtle install-button')}${button(menuIcon(4)+'設定','settings','subtle')}${button('友だちに教える','share:title:title','subtle share-entry')}<span>PROTOTYPE 0.19.6</span></div></section>`;updateMusicButton();}

function slots(){game=null;closeModal(false);setScreen('slots');app.innerHTML=`<section class="page">${chrome('冒険の記録')}<p class="intro">きみの工房をえらぼう</p><div class="slot-grid">${data.slots.map((s,i)=>{const parts=collectedParts(s),level=assemblyLevel(parts);return `<article class="save-slot"><button class="slot parchment visual-slot" data-action="slot:${i}"><span class="slot-heading"><small>LOGBOOK ${String(i+1).padStart(2,'0')}</small><span class="slot-number">${['Ⅰ','Ⅱ','Ⅲ'][i]}</span></span><span class="slot-airplane ${s?'':'unstarted'}">${planeArt(level,s||{})}</span><h3>${s?assemblyNames[level]:'新しい冒険'}</h3><span class="slot-progress">${s?`${s.cleared.length} / 30 ステージ · ${parts.length} / 5 部品 · <span class="stars">★</span> ${totalStars(s)} / ${MAX_STARS}`:'ルカと、ここから空をめざそう'}</span>${collectionStrip(parts)}<span class="slot-foot">${s?'つづきから · 工房をひらく →':'はじめる →'}</span></button>${standingBadge(s)}${s?`<button class="slot-share" data-action="share:slot:slots:${i}" aria-label="工房 ${i+1} の飛行機を共有する">共有する</button><button class="slot-delete" data-action="delete-slot:${i}" aria-label="工房 ${i+1} のセーブデータを消す">データを消す</button>`:''}</article>`;}).join('')}</div><p class="muted">記録は、この端末のブラウザに自動保存されます。</p></section>`;refreshStandings();}
function requestDeleteSlot(i){
 if(screen!=='slots'||!Number.isInteger(i)||i<0||i>=3)return;
 data=load();const record=data.slots[i];if(!record){slots();return;}
 const parts=chapters.filter((_,ci)=>record.cleared.includes(ci*6+5)).length;
 modal(`工房 ${i+1} のデータを消す？`,`<p class="delete-slot-summary">${record.cleared.length} / 30 ステージクリア<br>${parts} / 5 部品を獲得</p><p>この工房の冒険の記録と、飛行機のデザインを消します。<br><strong>消したデータは元に戻せません。</strong></p><p class="muted">ほかの工房の記録、ハイスコア、設定は残ります。</p><p class="delete-slot-error" role="alert" hidden></p>`,button('やめる','close','primary')+button('このデータを消す','confirm-delete-slot','danger-button'));
 pendingDelete={index:i,snapshot:JSON.stringify(record)};
 dialog.querySelector('[data-action="close"]').focus();
}
function deleteSlot(){
 if(screen!=='slots'||!dialog.open||!pendingDelete)return;
 const {index,snapshot}=pendingDelete,latest=load();
 if(JSON.stringify(latest.slots[index])!==snapshot){data=latest;slots();toast('記録が更新されています。消すデータをもう一度確認してね。');return;}
 const next={...latest,slots:latest.slots.map((record,i)=>i===index?null:record)};
 if(!save(next)){const error=dialog.querySelector('.delete-slot-error');error.hidden=false;error.textContent='データを消せませんでした。ブラウザの保存設定を確認してね。';return;}
 data=next;slots();toast(`工房 ${index+1} のデータを消しました`);
 app.querySelector(`[data-action="slot:${index}"]`).focus();
}
function openSlot(i){slot=i;if(!data.slots[slot]){data.slots[slot]=freshSlot();persist();if(arrivedViaShare){reportShareEvent('start',arrivedViaShare,'landing');arrivedViaShare=null;}map();opening();}else{map();if(voyageUnlocked(data.slots[slot]))return;const next=stages.find(t=>!data.slots[slot].cleared.includes(t.id))||stages[29];showChapterScene(next.chapter,{resume:true,onNext:()=>{}});}}
function conversation(story,done=()=>{},options={}){const g=game;if(g)g.paused=true;pointer=null;soundtrack.duck('story',true);showDialogue(story,()=>{soundtrack.duck('story',false);last=performance.now();if(game===g&&g&&!g.over)g.paused=false;done();},options);}
function unlocked(i){return i===0||data.slots[slot]?.cleared.includes(i-1);}
const chapterIcon=n=>`<i class="chapter-art" aria-hidden="true" style="--icon-x:${n%3*50}%;--icon-y:${Math.floor(n/3)*100}%"></i>`;
function map(){game=null;closeModal(false);setScreen('map');const s=data.slots[slot];app.innerHTML=`<section class="page map-page">${chrome(`工房 ${slot+1} · 冒険の地図`,'slots')}<div class="map-heading"><div><p class="eyebrow">THE JOURNEY TO THE SKY</p><h3>素材をあつめて、空へ。</h3></div><div>${button('はじまりの物語','prologue','subtle')}${button(chapterIcon(5)+'蒸気飛行機の工房','workshop','primary')}</div></div><div class="chapter-list">${chapters.map((c,ci)=>`<article class="chapter parchment" style="--chapter-color:${c.color}"><div class="chapter-info">${chapterIcon(ci)}<div><small>CHAPTER ${ci+1} / ${c.tag}</small><h3>${c.name}</h3><p>${c.part} · ${s.cleared.includes(ci*6+5)?'獲得済み':'素材を探そう'}</p><p class="chapter-star-count"><span class="stars" aria-hidden="true">★</span> ${chapterStars(s,ci)} / 18</p></div></div><div class="stage-list">${stages.slice(ci*6,ci*6+6).map(t=>`<button data-action="stage:${t.id}" ${!unlocked(t.id)?'disabled':''} class="stage ${s.cleared.includes(t.id)?'cleared':''} ${unlocked(t.id)&&!s.cleared.includes(t.id)?'next':''}" aria-label="${ci+1}-${t.step+1} ${t.name} 目標${t.target}"><b>${unlocked(t.id)?`${ci+1}-${t.step+1}`:'⌑'}</b><small>${s.cleared.includes(t.id)?(s.stars[t.id]?`<span class="stars">${starText(s.stars[t.id].stars)}</span>`:'✓'):`${t.target} をつくる`}</small></button>`).join('')}</div></article>`).join('')}</div>${voyageUnlocked(s)?skyMapCard(s):''}<p class="muted">${s.cleared.length} / 30 ステージクリア · <span class="stars">★</span> ${totalStars(s)} / ${MAX_STARS} · 好きなステージをもう一度遊べます。速く、石を割らずにクリアすると星がふえるよ</p></section>`;refreshStandings();}
function workshop(){game=null;closeModal(false);setScreen('workshop');const s=data.slots[slot],owned=collectedParts(s),level=assemblyLevel(owned),parts=owned.length;const paints=['青緑','夕焼け','夜空'];app.innerHTML=`<section class="page rich-workshop">${chrome('きみだけの蒸気飛行機','map')}<div class="hangar-layout"><div class="hangar-main parchment"><div class="hangar-heading"><div><p class="eyebrow">LUKA’S STEAM AIRPLANE</p><h2>${assemblyNames[level]}</h2></div><span class="build-count">${parts}<small> / 5 部品</small></span></div><div class="hangar-display">${planeArt(level,s)}<span class="hangar-badge">工房 ${slot+1} · ${paints[s.paint]}の機体</span></div>${level===5?planeNamePanel(s):''}${customizationPanel(s)}<div class="assembly-steps" aria-label="組み立ての進み具合">${assemblyNames.map((name,i)=>`<span class="${i<=level?'reached':''} ${i===level?'current':''}" title="${name}">${i===0?'START':i===5?'FLIGHT':String(i).padStart(2,'0')}</span>`).join('')}</div><p class="hangar-next">${level===5?'みんなの力を乗せて、雲の向こうへ。':`次は「${chapters[level].name}」で、${chapters[level].part}を集めよう。`}</p><div class="hangar-actions">${button(level===5?'✦ おじいちゃんと初飛行':'素材を探しにいく',level===5?'flight':'map','primary')}${button('組み立てを振り返る','assembly-replay','subtle')}${button('飛行機を共有','share:workshop:workshop','subtle share-entry')}</div></div><div class="hangar-inventory parchment"><p class="eyebrow">COLLECTION LOG</p><h3>冒険であつめた部品</h3>${chapters.map((c,i)=>`<div class="inventory-card ${owned.includes(i)?'owned':'missing'}">${partArt(i)}<div><small>第${i+1}章 · ${c.name}</small><strong>${c.part}</strong><span>${owned.includes(i)?'✓ 組み立て済み':`未獲得 · ${c.material}`}</span></div></div>`).join('')}</div></div>${voyageUnlocked(s)?skyMapCard(s)+treasureCollection(s):''}</section>`;refreshStandings();}
function customizationPanel(s){return `<div class="hangar-custom"><h3>飛行機のデザイン</h3><div class="custom-grid">${customizationOptions.map(o=>`<fieldset ${canCustomize(s,o.key)?'':'disabled'}><legend>${o.label}${canCustomize(s,o.key)?'':` · 第${o.part+1}章の部品で解放`}</legend><div class="choices">${o.options.map((label,n)=>`<button data-action="custom:${o.key}:${n}" class="${s[o.key]===n?'active':''}" aria-pressed="${s[o.key]===n}">${label}</button>`).join('')}</div></fieldset>`).join('')}</div><p class="custom-feedback" role="status" aria-live="polite">パーツを選ぶと、上の機体に反映されます。</p></div>`;}
function changeDesign(key,value){
 const s=data.slots[slot];if(screen!=='workshop'||!s||!canCustomize(s,key)||!Number.isInteger(value)||value<0||value>2)return;
 const next={...s,[key]:value,updated:Date.now()},nextData={...data,slots:data.slots.map((record,i)=>i===slot?next:record)};
 if(!save(nextData)){toast('デザインを保存できませんでした。もう一度試してね。');return;}data=nextData;soundtrack.play('assemble');
 const level=assemblyLevel(collectedParts(next));document.querySelector('.hangar-display .airplane-render').outerHTML=planeArt(level,next);
 const option=customizationOptions.find(o=>o.key===key);document.querySelectorAll(`[data-action^="custom:${key}:"]`).forEach(el=>{const selected=el.dataset.action===`custom:${key}:${value}`;el.classList.toggle('active',selected);el.setAttribute('aria-pressed',String(selected));});
 document.querySelector('.hangar-badge').textContent=`工房 ${slot+1} · ${customizationOptions[0].options[next.paint]}の機体`;
 document.querySelector('.custom-feedback').textContent=`${option.label}を「${option.options[value]}」にしました。保存済み！`;
}
function replayAssembly(){const s=data.slots[slot],owned=collectedParts(s);let i=0;const advance=()=>{while(i<5&&!owned.includes(i))i++;if(i===5){workshop();return;}const index=i++;showChapterScene(index,{clear:true,completed:owned.filter(n=>n<=index),previous:owned.filter(n=>n<index),paint:s.paint,design:s,onNext:advance,onMap:workshop,onShare:()=>share(index===4?'flight':'chapter','replay',{chapter:index})});};if(!owned.length){toast('最初の部品を集めたら、組み立てを見られるよ。');return;}advance();}
function challenge(mode){modal(mode==='score'?'スコアアタック':'エンドレス',`<p>${mode==='score'?'3分間で、どれだけエネルギーを集められる？':'ライフが続くかぎり、どこまでも。'}</p><p>「ミックス」では掛け算も使えるよ。</p><div class="best-list">足し算 BEST ${data.bests[mode+'-add']||0}<br>ミックス BEST ${data.bests[mode+'-mix']||0}</div>`,button('足し算で遊ぶ',`start:${mode}:add`,'primary')+button('ミックスで遊ぶ',`start:${mode}:mix`)+button('戻る','close','subtle'));}
function challengeStage(g){const pool=g.variant==='mix'?[stages[12],stages[18],stages[20],stages[21],stages[22],stages[28]]:[stages[0],stages[6],stages[12]];const t=pool[Math.min(Math.floor(g.done/5),pool.length-1)];return {...t,min:0,life:60,recover:9,count:Infinity,multiply:g.variant==='mix'};}
function briefStage(g,resume=false){if(game!==g||g.over)return;g.paused=true;pointer=null;showStageIntro(g.stage,{mode:g.mode,resume,remaining:g.stage.count-g.done,record:g.mode==='story'?data.slots[slot]?.stars?.[g.stage.id]||null:null,onStart:()=>{if(game!==g||g.over)return;g.paused=false;last=performance.now();}});}
function start(mode,id=0,variant='add',ranked=null,quick=false){if(mode==='sky'&&!voyageUnlocked(data.slots[slot]))return;soundtrack.duck('result',false);closeModal(false);game={mode,variant,ranked,stage:stages[id],path:[],op:'+',done:0,score:0,combo:0,paused:false,over:false,life:0,remaining:180,board:[],busy:false,pending:0,locked:new Set(),level:0,distance:0,skyLevel:0,hint:[],message:'数字をつないでみよう',failures:0,elapsed:0,breaks:0};if(mode==='sky'){game.seed=ranked?.seed??randomSeed();game.stage=voyageStage(game.seed);game.op='×';const record=voyageRecord(data.slots[slot].sky);record.flights++;data.slots[slot].sky=record;persist();}else if(mode!=='story')game.stage=challengeStage(game);game.life=game.stage.life;game.board=mode==='sky'?createSkyBoard(game.stage):createBoard(game.stage);setScreen('game');renderGame();last=performance.now();if(mode==='story'){game.paused=true;const g=game;if(quick){briefStage(g);return;}const begin=()=>conversation(stageStory(g.stage),()=>briefStage(g));if(game.stage.step===0)showChapterScene(game.stage.chapter,{silent:game.stage.id===0&&data.slots[slot].cleared.length===0&&data.slots[slot].failures===0,onNext:begin});else begin();return;}briefStage(game);}
function tileStyle(n){return `--stone:${palette[n]};background-size:500% 200%;background-position:${n%5*25}% ${Math.floor(n/5)*100}%;`;}
const hudArt=n=>`<i class="hud-art" aria-hidden="true" style="background-position:${n%3*50}% ${Math.floor(n/3)*100}%"></i>`;
function renderGame(){const g=game,sky=g.mode==='sky',c=sky?skyChapter:chapters[g.stage.chapter];app.innerHTML=`<section class="game-screen ${sky?'sky-voyage':''}"><div class="game-scenery" aria-hidden="true"><div class="game-landscape" ${sky?`data-region="${voyageRegion(g.stage).key}"`:`style="background-position:${(g.stage.chapter+1)%3*50}% ${Math.floor((g.stage.chapter+1)/3)*100}%"`}></div></div><aside class="mission"><div class="stage-sign parchment">${sky?`<small>SECRET CHAPTER 06</small><h2 id="region-name">${voyageRegion(g.stage).label}</h2><div class="region-track" aria-hidden="true"><i id="region-fill"></i></div><small id="region-progress" class="region-progress"></small>`:`<small>STAGE ${g.stage.chapter+1}-${g.stage.step+1}</small><h2>${c.name}</h2>`}</div><div class="target-medal"><small>お題</small><strong id="target">${g.stage.target}</strong><span>をつくろう！</span></div><div class="progress-card parchment"><span>${sky?'今回の飛距離':'できた数'}</span><b id="progress">0 / ${g.stage.count}</b></div><div class="guardian-card"><div class="guardian guardian-${g.stage.chapter}" role="img" aria-label="${c.guardian}">${sky?'<img class="sky-toto" src="/assets/sky-toto.webp" alt="">':hudArt(g.stage.chapter+1)}</div><div class="speech" id="guardian-text">力をかしてくれる？</div>${sky?`<span class="sky-mini-plane">${planeArt(5,data.slots[slot])}</span>`:''}</div><div class="reward parchment"><small>${sky?'最長飛距離':'ごほうび'}</small><b>${sky?`${voyageRecord(data.slots[slot].sky).best.toLocaleString()} m`:c.material}</b></div></aside><div class="puzzle"><div id="board" class="board" role="group" aria-label="数字の盤面。ドラッグ、または数字を選んで確定。">${g.board.map((n,i)=>`<button class="stone" data-index="${i}" style="${tileStyle(n)}" aria-label="${n}、${Math.floor(i/5)+1}行${i%5+1}列"><span class="sr-only">${n}</span></button>`).join('')}<svg id="trace" viewBox="0 0 500 500" aria-hidden="true"><polyline class="trace-shadow"/><polyline class="trace-line"/></svg></div><div class="equation parchment" aria-live="polite"><strong id="equation">数字をなぞろう</strong><small id="outcome">上下・左右・ななめにつながるよ</small></div><div class="puzzle-actions">${button('取り消す','cancel','subtle')}${button('確定する ↵','confirm','subtle')}</div></div><aside class="game-side"><div class="game-toolbar">${button('？','help','icon-button')}${button('Ⅱ','pause','icon-button')}</div><div class="boiler parchment"><label>${sky?'蒸気圧':'ライフ'} <span id="time-label"></span></label><div class="life-track"><div id="life-fill"></div></div><small id="combo">いい調子でいこう！</small></div><div class="advice speech" id="message">${g.stage.multiply?'足して準備、掛けて完成！':'小さな数は、まとめよう！'}</div>${sky?`<div class="sky-plane">${planeArt(5,data.slots[slot])}<span class="sky-boost-label"></span></div>`:`<div class="luka-portrait" role="img" aria-label="ルカ">${hudArt(0)}</div>`}<div class="operation"><button data-action="op:+" class="op active" aria-label="足し算"><span class="op-art" aria-hidden="true"></span><span class="op-label">足す</span></button><button data-action="op:×" class="op" ${g.stage.multiply?'':'disabled'} aria-label="掛け算${g.stage.multiply?'':'、火山の章で解放'}"><span class="op-art" aria-hidden="true"></span><span class="op-label">${g.stage.multiply?'掛ける':'未解放'}</span></button><span id="mode-status" class="sr-only" role="status" aria-live="polite"></span></div><div class="side-actions">${button('ひらめき','hint','subtle')}${button('並べなおす','shuffle','subtle')}</div></aside></section>`;wireBoard();updateHUD();}
function updateBoard(){if(!game||screen!=='game')return;document.querySelectorAll('.stone').forEach((el,i)=>{const n=game.board[i];el.style.cssText=tileStyle(n);el.setAttribute('aria-label',`${n}、${Math.floor(i/5)+1}行${i%5+1}列`);el.firstElementChild.textContent=n;});updateSelection();}
function updateSelection(){const g=game;if(!g||screen!=='game')return;updateOperation();document.querySelectorAll('.stone').forEach((el,i)=>{el.classList.toggle('selected',g.path.includes(i));el.classList.toggle('hinted',g.hint.includes(i));el.setAttribute('aria-pressed',String(g.path.includes(i)));});const points=g.path.map(i=>`${(i%5)*100+50},${Math.floor(i/5)*100+50}`).join(' ');$('#trace').querySelectorAll('polyline').forEach(p=>p.setAttribute('points',points));if(!g.path.length){$('#equation').textContent='数字をなぞろう';$('#outcome').textContent=g.message;return;}const value=total(g.board,g.path,g.op);$('#equation').textContent=g.path.map(i=>g.board[i]).join(` ${g.op} `)+` = ${value}`;const check=g.mode==='sky'?voyageEvaluate(g.board,g.path,g.op,g.stage.target):evaluate(g.board,g.path,g.op,g.stage.target);const kind=check.kind;if(check.message){$('#outcome').textContent=check.message;return;}$('#outcome').textContent=g.path.length<2?'もうひとつ、つないでみよう':kind==='success'?'ぴったり！ はなすと完成':kind==='merge'?`はなすと「${value}」に合体`:'石を消して整理（ライフ回復なし）';}
function updateHUD(){if(!game||screen!=='game')return;const g=game;$('#progress').textContent=g.mode==='sky'?`${g.distance.toLocaleString()} m`:g.mode==='story'?`${g.done} / ${g.stage.count}`:g.score.toLocaleString();$('#target').textContent=g.stage.target;if(g.mode==='sky')app.querySelector('.reward b').textContent=voyageRecord(data.slots[slot].sky).best.toLocaleString()+' m';const ratio=g.mode==='score'?g.remaining/180:g.life/g.stage.life;$('#life-fill').style.width=`${Math.max(0,ratio)*100}%`;$('#life-fill').classList.toggle('low',ratio<.25);$('#time-label').textContent=g.mode==='score'?`${Math.floor(Math.ceil(g.remaining)/60)}:${String(Math.ceil(g.remaining)%60).padStart(2,'0')}`:`${Math.ceil(g.life)}s`;$('#combo').textContent=g.combo>1?`${g.combo}連続成功！`:'ゆっくり考えてみよう';if(g.mode==='sky'){const region=voyageRegion(g.stage);$('#region-name').textContent=region.label;$('#region-fill').style.width=`${region.position/region.count*100}%`;$('#region-progress').textContent=`この領域 ${region.position} / ${region.count}`;}$('#guardian-text').textContent=g.mode==='sky'?`${g.stage.target}で、次の気流に乗るぞ！`:g.mode==='story'?`あと${g.stage.count-g.done}こ、お願い！`:`${g.done}こ完成！`;updateOperation();}
function updateOperation(){
 if(!game||screen!=='game')return;app.querySelector('.game-screen').dataset.op=game.op==='×'?'multiply':'add';
 document.querySelectorAll('.op').forEach(el=>{const active=el.dataset.action==='op:'+game.op;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});
}
function switchOperation(op,index=game?.path.at(-1)??12){
 if(!canPlay()||pointer!==null||game.path.length>1||op===game.op||(op!=='+'&&op!=='×')||(op==='×'&&!game.stage.multiply))return false;
 game.op=op;game.lastTap=null;game.hint=[];updateSelection();updateHUD();
 $('#mode-status').textContent=`${modeName(op)}に切り替えました`;
 soundtrack.play('assemble');soundtrack.play('success');operationFeedback($('#board'),index,op,0,true);return true;
}
function canPlay(){return game&&!game.paused&&!game.busy&&!game.over&&screen==='game'&&(game.mode!=='story'||game.done<game.stage.count);}
function stoneAvailable(i){return i>=0&&!game.locked.has(i%5);}
function updateLocks(){if(!game||screen!=='game')return;document.querySelectorAll('#board .stone').forEach((el,i)=>{const locked=!stoneAvailable(i);el.classList.toggle('motion-locked',locked);el.setAttribute('aria-disabled',String(locked));});for(const action of ['hint','shuffle']){const el=app.querySelector(`[data-action="${action}"]`);if(el)el.disabled=game.pending>0;}}
function pointIndex(x,y,drag=false){return traceIndex([...document.querySelectorAll('#board .stone')].map(el=>el.getBoundingClientRect()),x,y,drag);}
function addIndex(i){if(!canPlay()||!stoneAvailable(i))return;const p=extend(game.path,i);if(p!==game.path){soundtrack.play(p.length>game.path.length?'select':'back');game.path=p;game.hint=[];updateSelection();operationFeedback($('#board'),p.at(-1),game.op,total(game.board,p,game.op));}}
function wireBoard(){const b=$('#board');let gesture=null;
 b.addEventListener('pointerdown',e=>{if(!canPlay()||pointer!==null||e.button!==0)return;const i=pointIndex(e.clientX,e.clientY);if(!stoneAvailable(i))return;e.preventDefault();pointer=e.pointerId;b.setPointerCapture(pointer);gesture={index:i,x:e.clientX,y:e.clientY,time:performance.now(),type:e.pointerType,moved:false};/* A press always starts from the pressed stone: taps only move the selection, only a trace commits. */if(!(game.path.length===1&&game.path[0]===i))game.path=[];addIndex(i);});
 b.addEventListener('pointermove',e=>{if(pointer!==e.pointerId)return;if(gesture&&Math.hypot(e.clientX-gesture.x,e.clientY-gesture.y)>12){gesture.moved=true;game.lastTap=null;}if(canPlay())addIndex(pointIndex(e.clientX,e.clientY,true));});
 b.addEventListener('pointerup',e=>{if(pointer!==e.pointerId)return;const g=game,down=gesture;gesture=null;pointer=null;
 if(!canPlay()){if(g)g.lastTap=null;return;}
 addIndex(pointIndex(e.clientX,e.clientY,true));
 const now=performance.now(),tap=down&&!down.moved&&now-down.time<=250&&Math.hypot(e.clientX-down.x,e.clientY-down.y)<=12&&pointIndex(e.clientX,e.clientY)===down.index&&g.path.length===1?{index:down.index,x:e.clientX,y:e.clientY,time:now,type:e.pointerType}:null;
 if(tap&&g.stage.multiply&&isModeDoubleTap(g.lastTap,tap)){g.lastTap=null;g.path=[];updateSelection();switchOperation(g.op==='+'?'×':'+',tap.index);return;}
 g.lastTap=tap;if(down?.moved&&g.path.length>=2){g.lastTap=null;commit();}
 });
 const cancel=()=>{pointer=null;gesture=null;if(game){game.lastTap=null;game.path=[];updateSelection();}};
 b.addEventListener('pointercancel',cancel);b.addEventListener('lostpointercapture',e=>{if(pointer===e.pointerId)cancel();});
 b.addEventListener('keydown',e=>{if(game)game.lastTap=null;const i=Number(e.target.dataset.index);if(!Number.isInteger(i)||!canPlay())return;const offsets={ArrowRight:1,ArrowLeft:-1,ArrowUp:-5,ArrowDown:5};if(e.key in offsets){e.preventDefault();const n=i+offsets[e.key];if(n>=0&&n<25&&(!(e.key==='ArrowRight'||e.key==='ArrowLeft')||Math.floor(i/5)===Math.floor(n/5)))b.querySelector(`[data-index="${n}"]`).focus();}else if(e.key===' '){e.preventDefault();addIndex(i);}else if(e.key==='Enter'){e.preventDefault();if(game.path.length>=2)commit();else addIndex(i);}else if(e.key==='Escape'){game.path=[];updateSelection();}});}
async function commit(){
 if(!canPlay())return;
 const g=game,t=g.stage,targetLevel=g.skyLevel,path=[...g.path],op=g.op,columns=new Set(path.map(i=>i%5));
 if([...columns].some(c=>g.locked.has(c)))return;
 const result=g.mode==='sky'?voyageEvaluate(g.board,path,op,t.target):evaluate(g.board,path,op,t.target);if(result.kind==='cancel'){if(result.message)toast(result.message);return;}
 const board=$('#board'),spawn=g.mode==='sky'?()=>skySpawn(t):()=>t.min+Math.floor(Math.random()*(t.max-t.min+1));
 const next=resolve(g.board,path,op,t.target,spawn).board;
 g.pending++;columns.forEach(c=>g.locked.add(c));g.path=[];g.hint=[];pointer=null;updateSelection();updateLocks();
 const current=()=>game===g&&!g.over&&board.isConnected;let applied=false;
 const apply=()=>{if(!current()||applied)return;for(let i=0;i<25;i++)if(columns.has(i%5))g.board[i]=next[i];applied=true;updateBoard();};
 try{await gatherStones({board,path,op,result,tileStyle,play:name=>soundtrack.play(name),current,apply});}
 catch{if(current())apply();}
 finally{g.pending--;columns.forEach(c=>g.locked.delete(c));}
 if(!current())return;apply();
 if(result.kind==='success'){g.done++;g.combo++;g.score+=100+Math.min(g.combo-1,10)*20;if(g.mode!=='score')g.life=Math.min(t.life,g.life+t.recover);g.message=`${result.value} 完成！ よくできた！`;}
 else if(result.kind==='merge')g.message=`「${result.value}」に合体したよ`;
 else{g.combo=0;if(g.mode==='story')g.breaks++;g.message='石を整理したよ。次はお題をつくろう';}
 if(g.mode==='sky'&&result.kind==='success')recordSkyDistance(g,result.value,targetLevel);$('#message').textContent=g.message;updateSelection();updateHUD();updateLocks();
 if(g.pending)return;
 if(g.mode==='sky'){advanceSky(g);return;}
 if(g.mode==='story'&&g.done>=t.count){finish(true);return;}
 if(g.mode!=='story'&&!g.path.length&&pointer===null&&Math.floor(g.done/5)>g.level){g.level=Math.floor(g.done/5);g.stage=challengeStage(g);g.board=createBoard(g.stage);g.path=[];g.op='+';pointer=null;renderGame();toast(`次は ${g.stage.target} をつくろう！`);}
}

function finish(win){const g=game;if(!g||g.over)return;if(g.mode==='sky'){returnSky('steam');return;}g.over=true;g.paused=true;pointer=null;soundtrack.duck('result',true);soundtrack.play(win?(g.stage.step===5?'chapter':'clear'):'failure');if(g.mode==='story'){const s=data.slots[slot];if(win){const previous=collectedParts(s);if(!s.cleared.includes(g.stage.id))s.cleared.push(g.stage.id);s.failures=0;const rating=rateRun(g.stage,{time:g.elapsed,breaks:g.breaks}),run={stars:rating.stars,time:rating.time,breaks:rating.breaks},before=s.stars[g.stage.id]||null,best=betterRecord(before,run),improved=best===run&&(!before||before.stars!==run.stars||before.breaks!==run.breaks||before.time!==run.time);s.stars={...s.stars,[g.stage.id]:best};s.updated=Date.now();persist();const c=chapters[g.stage.chapter];const record={...run,improved,goal:rating.goal};const last=g.stage.step===5;/* Chapter-final stages show the regular star modal first; つづける then opens the chapter clear scene. */const scene=()=>showChapterScene(g.stage.chapter,{clear:true,completed:collectedParts(s),previous,paint:s.paint,design:s,record,onNext:()=>g.stage.id===29?act('flight'):start('story',g.stage.id+1),onMap:map,onShare:()=>share(g.stage.id===29?'flight':'chapter','clear',{chapter:g.stage.chapter})});pendingScene=last?scene:null;modal('ステージクリア！',`${victoryEffects()}<div class="victory-hero"><img src="./assets/luka-victory.webp" width="640" height="640" alt="笑顔でガッツポーズするルカ"></div><p>${last?`第${g.stage.chapter+1}章、最後のステージをクリア！`:'ありがとう！ もう少しで素材が集まりそうだよ。'}</p><h3>${g.stage.count}回、完成！</h3>${starBlock(record)}`,last?button('つづける ▸','chapter-scene','primary')+button('もう一度',`retry:${g.stage.id}`)+button('共有する',`share:stage:clear:${g.stage.id}`,'subtle share-entry'):button('次へ',`stage:${g.stage.id+1}`,'primary')+button('もう一度',`retry:${g.stage.id}`)+button('冒険の地図へ','map')+button('共有する',`share:stage:clear:${g.stage.id}`,'subtle share-entry'));}else{s.failures++;persist();modal('もう一度、やってみよう',`<p>集めた素材はなくならないよ。</p><p>${g.done} / ${g.stage.count} 回できたね。小さい石を合体させるのもコツだよ。</p>${s.failures>=2?'<p>設定で「ゆっくりライフ」にすると、考える時間が長くなるよ。</p>':''}`,button('もう一度',`retry:${g.stage.id}`,'primary')+button('ゆっくりで再挑戦',`slow-retry:${g.stage.id}`)+button('地図へ','map'));}}else{const key=g.mode+'-'+g.variant,record=g.score>(data.bests[key]||0);data.bests[key]=Math.max(g.score,data.bests[key]||0);persist();modal(g.mode==='score'?'タイムアップ！':'冒険の記録',`<p>${record?'NEW BEST!':'SCORE'}</p><div class="result-score">${g.score.toLocaleString()}</div><p>${g.done}こ完成 · ${g.variant==='mix'?'ミックス':'足し算'}</p>`,button('もう一度',`start:${g.mode}:${g.variant}`,'primary')+button('タイトルへ','title'));}}
function pause(){if(!game||game.over)return;game.path=[];updateSelection();modal('ひとやすみ',`<p>ライフと時間は止まっています。</p>`,button('つづける','resume-game','primary')+button('設定','settings')+button('冒険をやめる','quit','subtle'));}
function help(){if(game?.mode==='sky'){modal('空の旅のあそびかた','<p>となりあう石を×でつなぎ、お題の数字を作ろう。できた数字の分だけ飛行機が進むよ。空は雲の海、夕映えの回廊、星の高み、果ての空と続き、奥へ進むほどお題は大きくなる。領域に入ると気流が変わり、お題は小さな数からまた高くなっていく。</p><p>＋で一桁の石を準備できるよ。0を×でつなぐと石は消えるだけ、1は答えを変えない中継役。成功すると蒸気圧が回復。尽きたら工房へ帰還します。</p><p>飛距離は成功のたびに保存。秘宝は累計飛距離で集まるよ。</p><p class="muted">タップは石を選ぶだけ。なぞって指をはなすと確定。同じ石をダブルタップすると＋と×が切り替わり、選択は外れます。</p>',button('わかった！','close','primary'));return;}modal('あそびかた',`<ol class="instructions"><li>となりあう数字を、上下・左右・ななめになぞろう。</li><li>お題と同じ数なら成功！ ライフが回復。</li><li>お題より小さく、0〜9なら最後の場所に合体。</li><li>それ以外は石が消えるだけ。ライフは回復しないよ。</li><li>火山からは「×」も使える。6×6で36を作れるよ。</li></ol><p class="muted">タップは石を選ぶだけ。なぞって指をはなすと確定。同じ石をダブルタップすると＋と×が切り替わり、選択は外れます。</p><p class="muted">PC：方向キーで移動、Spaceで石を選択、Enterで確定。ひとつ前に戻ると選択を取り消せます。</p>`,button('わかった！','close','primary'));}
function updateMusicButton(){const el=document.querySelector('[data-action="music-toggle"]');if(!el)return;const on=soundtrack.settings.music&&soundtrack.settings.musicVolume>0,playing=on&&soundtrack.unlocked&&soundtrack.context?.state==='running';el.textContent=playing?'音楽 ON':on?'音楽を再生':'音楽 OFF';el.setAttribute('aria-pressed',String(playing));el.setAttribute('aria-label',playing?'BGMをオフにする':'BGMを再生する');}
function settings(){const a=soundtrack.settings;modal('設定',`<div class="audio-settings"><div class="audio-setting"><label class="setting"><span>BGM</span><input type="checkbox" id="music" ${a.music?'checked':''}></label><label class="volume-setting" for="music-volume"><span>音楽の音量</span><output id="music-value">${Math.round(a.musicVolume*100)}%</output><input id="music-volume" type="range" min="0" max="100" step="5" value="${Math.round(a.musicVolume*100)}"></label></div><div class="audio-setting"><label class="setting"><span>効果音</span><input type="checkbox" id="sound" ${a.sound?'checked':''}></label><label class="volume-setting" for="sound-volume"><span>効果音の音量</span><output id="sound-value">${Math.round(a.soundVolume*100)}%</output><input id="sound-volume" type="range" min="0" max="100" step="5" value="${Math.round(a.soundVolume*100)}"></label></div></div><p class="audio-save-status muted" role="status">音の設定は変更すると保存されます。</p><label class="setting"><span>ゆっくりライフ<br><small>ストーリーだけ、減る速さを半分に</small></span><input type="checkbox" id="slow" ${data.settings.slow?'checked':''}></label>${creditsHTML}<p class="muted">冒険の記録は、このブラウザに保存されます。</p>`,button('保存して戻る','save-settings','primary')+button('全画面表示','fullscreen','subtle')+button('ゲームを共有','share:title:settings','subtle share-entry'));}

function flight(){game=null;closeModal(false);setScreen('flight');app.innerHTML=`<section class="flight-screen"><div class="parchment ending"><p class="eyebrow">A NEW HORIZON</p><h1>雲の、その先へ。</h1><p>「おじいちゃん、見て！ 新しい島だ！」</p><p>森の木、海の金属、洞窟の結晶。<br>みんなの力を乗せて、ルカの飛行機は空へ。</p><p>「さあ、次はどこへ行こうか」</p>${voyageUnlocked(data.slots[slot])?`<p class="sky-unlocked">✦ 隠し第6章「トトじいと空の旅」解放！</p>${button('空の旅へ出発','sky-deck','primary')}`:''}${button('完成を共有','share:flight:ending','subtle share-entry')}${button('工房へ帰る','workshop','subtle')}</div></section>`;}
function hint(){if(!canPlay()||game.pending)return;soundtrack.play('hint');const found=game.mode==='sky'?voyageSolution(game.board,game.stage.target):solution(game.board,game.stage.target,game.stage.multiply?['+','×']:['+']);if(found){game.hint=found.path;game.op=found.op;game.path=[];game.message=`${found.op} で、光る石をつないでみよう`;updateSelection();updateHUD();$('#message').textContent=game.message;}else toast('小さな数字を合体させて準備しよう。並べなおすこともできるよ。');}
function shuffle(){if(!canPlay()||game.pending)return;modal('盤面を並べなおす？','<p>新しい石を補充します。ライフ・蒸気圧を5秒使うよ。</p>',button('並べなおす','do-shuffle','primary')+button('やめる','close'));}
function act(action){if(!action)return;if(game)game.lastTap=null;const [a,b,c]=action.split(':');switch(a){case'music-toggle':if(!soundtrack.unlocked||!soundtrack.settings.music||!soundtrack.settings.musicVolume){soundtrack.configure({music:true,musicVolume:soundtrack.settings.musicVolume||.45});soundtrack.unlock();}else soundtrack.configure({music:false});break;case'title':title();break;case'slots':slots();break;case'slot':openSlot(Number(b));break;case'delete-slot':requestDeleteSlot(Number(b));break;case'confirm-delete-slot':deleteSlot();break;case'map':map();break;case'workshop':workshop();break;case'assembly-replay':replayAssembly();break;case'custom':changeDesign(b,Number(c));break;case'stage':if(unlocked(Number(b)))start('story',Number(b));break;case'chapter-scene':{const scene=pendingScene;pendingScene=null;if(!scene)break;closeModal(false);scene();break;}case'retry':if(unlocked(Number(b)))start('story',Number(b),'add',null,true);break;case'slow-retry':data.settings.slow=true;persist();if(unlocked(Number(b)))start('story',Number(b),'add',null,true);break;case'plane-name':namePlane();break;case'save-plane-name':savePlaneName();break;case'rankings':showRankings('sky-deck');break;case'season':showRankings(rankingBack,Number(b));break;case'share':shareAction(b,c,action.split(':').slice(3));break;case'standing':{const i=Number(b);if(Number.isInteger(i)&&i>=0&&i<3&&voyageUnlocked(data.slots[i])){const back=screen==='slots'?'slots':screen==='map'?'map':screen==='workshop'?'workshop':'sky-deck';slot=i;showRankings(back);}break;}case'sky-ranked-start':void rankedStart();break;case'sky-deck':skyDeck();break;case'sky-start':start('sky');break;case'sky-return':requestSkyReturn();break;case'sky-return-confirm':returnSky();break;case'close':closeModal();break;case'resume-game':closeModal(false);briefStage(game,true);break;case'help':help();break;case'settings':settings();break;case'save-settings':data.settings.sound=soundtrack.settings.sound;data.settings.slow=$('#slow').checked;persist();closeModal();break;case'pause':pause();break;case'quit':if(game?.mode==='sky'){requestSkyReturn();break;}modal('冒険をやめる？','<p>このステージの途中経過は保存されません。クリア済みの記録は残ります。</p>',button('やめる',game.mode==='story'?'map':'title')+button('つづける','close','primary'));break;case'op':switchOperation(b);break;case'cancel':if(canPlay()){game.path=[];updateSelection();}break;case'confirm':commit();break;case'hint':hint();break;case'shuffle':shuffle();break;case'do-shuffle':if(game&&!game.pending){soundtrack.play('shuffle');game.board=game.mode==='sky'?createSkyBoard(game.stage):createBoard(game.stage);game.path=[];game.hint=[];if(game.mode==='score')game.remaining=Math.max(0,game.remaining-5);else game.life=Math.max(0,game.life-5);closeModal();updateBoard();updateHUD();if(game.life<=0||game.remaining<=0)finish(false);}break;case'flight':closeModal(false);conversation(epilogue,flight);break;case'prologue':opening();break;case'install':requestInstall().then(result=>{if(result==='installed'){toast('ホーム画面から起動しています');return;}if(result==='instructions')modal('ホーム画面に追加','<p>iPhone・iPadでは、Safariの共有メニューから「ホーム画面に追加」を選んでね。</p><p>「Webアプリとして開く」が表示されたらオンにします。</p><p>Android・PCでは、ブラウザの「アプリをインストール」を選べます。</p><p class="muted">初回はネットにつないで開いてね。読み込み後はオフラインでも遊べます。<br>ブラウザ版とホーム画面版の記録が別になる端末があります。</p>',button('わかった！','close','primary'));});break;case'fullscreen':if(document.documentElement.requestFullscreen)document.documentElement.requestFullscreen().catch(()=>toast('この端末では全画面にできません'));else toast('横向きで遊んでね。Safariでは共有→ホーム画面に追加も使えます。');break;}}
app.addEventListener('click',e=>act(e.target.closest('[data-action]')?.dataset.action));dialog.addEventListener('click',e=>act(e.target.closest('[data-action]')?.dataset.action));dialog.addEventListener('cancel',e=>{e.preventDefault();if(game?.over)return;closeModal();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&!game.over&&!game.paused)pause();});window.addEventListener('blur',()=>{if(game&&!game.over&&!game.paused)pause();});
function tick(now){if(game?.mode==='sky')advanceSky(game);const dt=(now-last)/1000;last=now;if(game&&game.mode==='story'&&!game.paused&&!game.over&&!document.hidden)game.elapsed+=dt;if(canPlay()&&!game.pending&&!document.hidden){if(game.mode==='score'){game.remaining=Math.max(0,game.remaining-dt);if(game.remaining<=0)finish(false);}else{game.life=Math.max(0,game.life-dt*(game.mode==='story'&&data.settings.slow ? 0.5 : 1));if(game.life<=0)finish(false);}updateHUD();}requestAnimationFrame(tick);}
title();requestAnimationFrame(tick);

// All playback starts from a gesture. Hidden pages suspend the single audio context.
soundtrack.onChange=updateMusicButton;
for(const event of ['pointerdown','keydown'])document.addEventListener(event,e=>{if(e.target.closest?.('[data-action="music-toggle"]'))return;if(event==='keydown'&&(e.repeat||e.metaKey||e.ctrlKey||e.altKey))return;soundtrack.unlock();},{capture:true});
document.addEventListener('visibilitychange',()=>soundtrack.visibility(document.hidden));
window.addEventListener('pagehide',()=>soundtrack.visibility(true));
window.addEventListener('pageshow',()=>soundtrack.visibility(document.hidden));
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled||b.classList.contains('stone'))return;const action=b.dataset.action||'';if(/^(music-toggle|hint|do-shuffle|custom:|confirm)/.test(action))return;soundtrack.play(['title','slots','map','close'].includes(action)?'back':'click');});
dialog.addEventListener('input',e=>{const mappings={music:'music',sound:'sound','music-volume':'musicVolume','sound-volume':'soundVolume'},key=mappings[e.target.id];if(!key)return;const volume=e.target.type==='range',value=volume?Number(e.target.value)/100:e.target.checked;const ok=soundtrack.configure({[key]:value});if(volume)$('#'+(key==='musicVolume'?'music':'sound')+'-value').textContent=Math.round(value*100)+'%';const status=dialog.querySelector('.audio-save-status');status.textContent=ok?'音の設定を保存しました。':'このブラウザでは音の設定を保存できません。';if(key==='soundVolume'||key==='sound')soundtrack.play('select');});
document.addEventListener('miracle:chapter',e=>{soundtrack.duck('chapter',e.detail.open);if(e.detail.open&&!e.detail.clear&&!e.detail.silent)soundtrack.play('arrival');});
document.addEventListener('miracle:brief',e=>{soundtrack.duck('brief',e.detail.open);if(e.detail.open)soundtrack.play('intro');});
document.addEventListener('miracle:assembly',()=>soundtrack.play('assemble'));
document.addEventListener('miracle:region',e=>{soundtrack.duck('chapter',e.detail.open);if(e.detail.open)soundtrack.play('arrival');});

function skyMapCard(s){const r=voyageRecord(s.sky);return `<article class="sky-map-card parchment"><div><p class="eyebrow">SECRET CHAPTER 06</p><h2>トトじいと空の旅</h2>${standingBadge(s)}<p>完成した飛行機で、まだ知らない空へ。</p><p>最長 ${r.best.toLocaleString()} m · 秘宝 ${r.treasures.length} / 6</p>${button('空の旅をひらく','sky-deck','primary')}</div>${planeArt(5,s)}</article>`;}
function skyDeck(){if(!voyageUnlocked(data.slots[slot]))return;game=null;closeModal(false);setScreen('flight');const s=data.slots[slot],r=voyageRecord(s.sky);app.innerHTML=`<section class="page sky-deck">${chrome('第6章 · トトじいと空の旅','map')}<div class="sky-departure parchment"><div class="sky-departure-art">${planeArt(5,s)}<img src="/assets/sky-toto.webp" alt="操縦席のトトじい"></div><div><p class="eyebrow">BEYOND THE CLOUDS</p><h1>ふたりで、どこまでも。</h1>${standingBadge(s)}<p>空は<strong>雲の海</strong>からはじまり、夕映えの回廊、星の高み、そして果ての空へ。奥の領域へ進むほど、お題の数は大きくなるよ。お題ができると、その数字の分だけ飛べる。</p><p>0や1の石も落ちてくる。＋で数を作って、かけ算の準備をしよう。成功で蒸気圧が回復。蒸気が尽きたら帰還しよう。飛距離と秘宝は成功のたびに保存されるよ。</p><p>最長 <strong>${r.best.toLocaleString()} m</strong> · 累計 ${r.total.toLocaleString()} m</p>${planeNamePanel(s)}<div class="sky-deck-actions">${button('トトじいと飛び立つ','sky-start','primary')}${button('ランキングに参加して飛ぶ','sky-ranked-start')}${button('空の旅ランキング','rankings','subtle')}${button('出発を共有','share:sky:deck','subtle share-entry')}</div><p class="muted">ランキングは任意参加。自己ベストを達成したときの名前と機体が載るよ。</p></div></div>${treasureCollection(s)}</section>`;refreshStandings();}
function recordSkyDistance(g,value,targetLevel){rankings.goal(g.ranked,targetLevel,value);g.distance=Math.min(Number.MAX_SAFE_INTEGER,g.distance+value);const s=data.slots[slot],before=voyageRecord(s.sky);s.sky=addDistance(before,value,g.distance);s.updated=Date.now();persist();g.message=`${value.toLocaleString()} m進んだ！ 次の空へ！`;const found=s.sky.treasures.filter(i=>!before.treasures.includes(i));if(found.length){toast(`秘宝「${found.map(i=>treasures[i].name).join('・')}」を発見！`);soundtrack.play('chapter');}const plane=app.querySelector('.sky-plane');if(plane){plane.classList.remove('boost');void plane.offsetWidth;plane.classList.add('boost');plane.querySelector('.sky-boost-label').textContent=`+${value.toLocaleString()} m`;}}
/* Cross-fade the voyage backdrop to the illustration of the region the flight just entered. */
function skyBackdrop(g){const scenery=app.querySelector('.sky-voyage .game-scenery');if(!scenery)return;const key=voyageRegion(g.stage).key;if(scenery.lastElementChild?.dataset.region===key)return;const old=[...scenery.querySelectorAll('.game-landscape')],layer=document.createElement('div');layer.className='game-landscape region-enter';layer.dataset.region=key;scenery.append(layer);setTimeout(()=>{if(layer.isConnected)for(const el of old)el.remove();},1600);}
function advanceSky(g){if(game!==g||g.over||g.paused||g.pending||g.path.length||pointer!==null||g.skyLevel===g.done)return;g.skyLevel=g.done;const before=g.stage.set;g.stage=voyageStage(g.seed,g.done);g.op='×';g.hint=[];updateBoard();updateHUD();if(g.stage.set!==before){g.paused=true;pointer=null;showRegionCutin(g.stage,{onContinue:()=>{if(game!==g||g.over)return;skyBackdrop(g);g.paused=false;last=performance.now();}});return;}$('#target').animate([{transform:'scale(.7)',opacity:.3},{transform:'scale(1)',opacity:1}],{duration:matchMedia('(prefers-reduced-motion: reduce)').matches?0:350});}
function requestSkyReturn(){if(game?.mode!=='sky'||game.over)return;if(game.pending){toast('石が落ち着いたら、帰還できるよ');return;}modal('工房へ帰還する？','<p>ここまでの飛距離と秘宝は保存されています。</p>',button('帰還する','sky-return-confirm','primary')+button('旅をつづける','close'));}
function returnSky(reason='return'){const g=game;if(!g||g.mode!=='sky'||g.over||g.pending)return;rankings.finish(g.ranked,reason);g.over=true;g.paused=true;pointer=null;const r=voyageRecord(data.slots[slot].sky);soundtrack.duck('result',true);soundtrack.play('arrival');modal('おかえり、空の旅人！',`<p>トトじい「いい旅じゃった。また飛ぼう！」</p>${rankMessage(g.ranked)}<div class="result-score">${g.distance.toLocaleString()}<small> m</small></div><p>最長 ${r.best.toLocaleString()} m · 累計 ${r.total.toLocaleString()} m<br>秘宝 ${r.treasures.length} / 6</p>`,button('もう一度、空へ',g.ranked?'sky-ranked-start':'sky-start','primary')+button('空の旅ランキング','rankings')+button('秘宝を見る','sky-deck')+button('工房へ','workshop')+button('結果を共有',`share:voyage:return:${g.distance}`,'subtle share-entry'));}

function planeNamePanel(s){return `<div class="plane-name-panel"><small>きみの飛行機の名前</small><strong>${esc(s.flightName||'まだ名前がありません')}</strong>${button(s.flightName?'名前を変える':'飛行機に名前をつける','plane-name','subtle')}</div>`;}
let afterName=null;
/* The dialog sits in the top layer, so toasts are hidden behind it: every message about the name is shown inside the dialog. */
function nameError(text){const field=$('#plane-name'),note=$('#plane-name-error');if(!field||!note)return;note.textContent=text;field.setAttribute('aria-invalid',text?'true':'false');if(text)field.focus();}
function namePlane(done=null,notice=''){afterName=done;modal('飛行機に名前をつけよう',`<p>この名前で、空の旅ランキングに載るよ。</p><label class="plane-name-label" for="plane-name">飛行機の名前（20文字まで）</label><input id="plane-name" maxlength="40" autocomplete="off" value="${esc(data.slots[slot].flightName)}" placeholder="例：そらいろ号" aria-describedby="plane-name-error" aria-invalid="${notice?'true':'false'}"><p id="plane-name-error" class="plane-name-error" role="alert">${esc(notice)}</p><p class="muted">ランキングと共有カードでみんなに見える名前です。本名・電話番号・住所・SNSの名前は入れないでね。らんぼうな言葉の名前は使えません。</p>`,button('この名前にする','save-plane-name','primary')+button('やめる','close','subtle'));const field=$('#plane-name');field.addEventListener('input',()=>{if($('#plane-name-error')?.textContent)nameError('');});field.focus();}
function savePlaneName(){const name=flightName($('#plane-name')?.value);if(!name){nameError('飛行機の名前を入れてね');return;}const issue=nameIssue(name);if(issue){nameError(nameIssueMessage(issue));return;}data.slots[slot].flightName=name;data.slots[slot].updated=Date.now();if(!save(data)){nameError('名前を保存できませんでした。もう一度ためしてね。');return;}const done=afterName;afterName=null;closeModal();if(done){done();return;}if(screen==='workshop')workshop();else skyDeck();}
function rankMessage(run){return `<p class="ranking-status" ${run?`data-rank-run="${esc(run.runId)}"`:''} role="status">${esc(rankStatus(run))}</p>`;}
async function rankedStart(){
 if(rankingStarting||!voyageUnlocked(data.slots[slot]))return;const s=data.slots[slot];if(!s.flightName||nameIssue(s.flightName)){namePlane(()=>void rankedStart(),s.flightName?'いまの名前はランキングに載せられなくなりました。'+nameIssueMessage(nameIssue(s.flightName)):'');return;}rankingStarting=true;
 modal('出発の準備中','<p>飛行機を登録しています。出発後は通信を待たずに遊べます。</p>',button('通信なしで飛ぶ','sky-start','subtle'));
 const stillHere=()=>dialog.open&&dialog.querySelector('h2')?.textContent==='出発の準備中'&&data.slots[slot]===s;
 try{const run=await rankings.begin(s,()=>save(data));if(stillHere())start('sky',0,'add',run);else rankings.exclude(run);}catch(e){if(!stillHere())return;if(e?.message==='VERSION')modal('ゲームの更新が必要です','<p>空の旅のルールが新しくなりました。タイトル画面に戻って更新すると、ランキングに参加できます。</p><p>通常の空の旅は、そのまま遊べます。</p>',button('通信なしで飛ぶ','sky-start','primary')+button('タイトルへ','title','subtle'));else modal('今はランキングに接続できません','<p>通常の空の旅は、そのまま遊べます。</p><p>ランキングが利用できるようになったら、もう一度参加してね。</p>',button('通信なしで飛ぶ','sky-start','primary')+button('出発画面へ','sky-deck','subtle'));}finally{rankingStarting=false;}
}
let rankingBack='sky-deck';
async function showRankings(back=rankingBack,season=null){
 if(!voyageUnlocked(data.slots[slot]))return;game=null;closeModal(false);setScreen('rankings');const s=data.slots[slot];rankingBack=back;
 app.innerHTML=`<section class="page ranking-page">${chrome('空の旅ランキング',back)}<div class="ranking-heading"><p class="eyebrow">HALL OF SKY VOYAGERS</p><h1>その翼で、どこまでも。</h1><p>一度の旅で飛んだ距離 · 上位100機</p></div><div id="ranking-seasons" class="ranking-seasons" aria-label="シーズン"></div><div id="ranking-content" role="status" aria-live="polite"><p class="parchment ranking-empty">空の旅の記録を読み込んでいます…</p></div>${rankings.runs.filter(r=>r.uid===s.ranking?.uid&&r.closed&&r.status!=='finished').map(rankMessage).join('')}</section>`;
 const content=$('#ranking-content'),seasonsBox=$('#ranking-seasons');
 try{const result=await rankings.api('board',{season});if(!content.isConnected)return;const current=result.season?.current!==false;lastBoard=current?result.entries:[];
  // Every rule change starts a season with its own board; older seasons stay readable but cannot be shared as a current rank.
  seasonsBox.innerHTML=(result.seasons||[]).length>1?`<p class="eyebrow">SEASON</p><div class="season-tabs" role="tablist">${result.seasons.map(item=>`<button type="button" role="tab" aria-selected="${item.id===result.season.id}" class="season-tab ${item.id===result.season.id?'active':''}" data-action="season:${item.id}">${item.current?'現在':'過去'} · ${esc(item.name)}</button>`).join('')}</div><p class="season-note muted">${current?'今のシーズンの記録。ルールが変わると新しいシーズンがはじまり、前の記録はここに残ります。':'終わったシーズンの記録です。新しい記録は現在のシーズンに載ります。'}</p>`:'';
  content.innerHTML=result.entries.length?`<ol class="ranking-list">${result.entries.map(row=>`<li class="ranking-row parchment ${row.uid===s.ranking?.uid?'is-mine':''}"><span class="ranking-place">${row.rank}<small>位</small></span><div class="ranking-plane">${planeArt(5,row.design)}</div><div class="ranking-name"><strong>${esc(row.name)}</strong>${row.uid===s.ranking?.uid?`<small>あなたの機体</small>${current?`<button type="button" class="ranking-share" data-action="share:rank:ranking:${row.rank}">この順位を共有</button>`:''}`:''}</div><b class="ranking-distance">${Number(row.distance).toLocaleString()}<small> m</small></b></li>`).join('')}</ol>`:`<div class="parchment ranking-empty"><h2>${current?'最初の空の旅人になろう。':'このシーズンの記録はありません。'}</h2><p>${current?'ランキングに参加して飛び、帰還すると記録が載るよ。':'現在のシーズンで、新しい記録に挑戦しよう。'}</p></div>`;}
 catch{if(content.isConnected)content.innerHTML='<div class="parchment ranking-empty"><h2>ランキングは準備中です。</h2><p>接続できないときも、空の旅や秘宝集めはそのまま楽しめます。</p></div>';}
}

function standingBadge(s){return s?.ranking?.uid?`<button type="button" class="own-standing" data-action="standing:${data.slots.indexOf(s)}" data-standing="${esc(s.ranking.uid)}" aria-live="polite">現在の順位を確認中…</button>`:'';}
async function refreshStandings(){
 const elements=[...app.querySelectorAll('[data-standing]')];
 await Promise.allSettled(data.slots.filter(s=>s?.ranking?.uid&&elements.some(e=>e.dataset.standing===s.ranking.uid)).map(async s=>{
  const targets=elements.filter(e=>e.dataset.standing===s.ranking.uid);
  try{const result=await rankings.api('standing',{},s.ranking.key);for(const el of targets){if(!el.isConnected)continue;el.classList.toggle('ranked',result.rank!==null&&result.rank<=100);el.classList.toggle('podium',result.rank!==null&&result.rank<=3);el.innerHTML=result.rank===null?'空の旅 · まだランキング記録がありません':`<span>${result.rank<=100?'✦ TOP 100':'空の旅ランキング'}</span><strong>現在 ${Number(result.rank).toLocaleString()} 位</strong><small>${Number(result.distance).toLocaleString()} m</small><small class="standing-link">ランキングを見る →</small>`;}}
  catch{for(const el of targets)if(el.isConnected)el.textContent='現在の順位は、接続後に確認できます';}
 }));
}

let lastBoard=[];
function starBlock(record){return `<div class="star-result" data-stars="${record.stars}"><span class="stars star-big" role="img" aria-label="${record.stars}つ星">${starText(record.stars)}</span><span class="star-metrics">タイム ${formatTime(record.time)} · 割った回数 ${record.breaks}${record.improved?'<b class="star-new">新記録！</b>':''}</span><span class="star-goal">${record.stars===3?'完璧！ 3つ星の記録だよ':`3つ星の条件: ${goalText(record.goal)}`}</span></div>`;}
/* Every share is a public snapshot of the current workshop; the dialog never changes the save. */
function share(kind,entry,extra={},record=data.slots[slot]){const snapshot=createSnapshot(kind,kind==='title'?null:record,extra);if(!snapshot){toast('今は共有できません');return;}openShareDialog(snapshot,{entry,origin:location.origin});}
function shareAction(kind,entry,rest){
 const s=data.slots[slot];
 switch(kind){
  case 'title':share('title',entry);break;
  case 'slot':{const i=Number(rest[0]);if(Number.isInteger(i)&&data.slots[i])share('slot',entry,{},data.slots[i]);break;}
  case 'workshop':if(s)share('workshop',entry);break;
  case 'stage':{const id=Number(rest[0]);if(s&&Number.isInteger(id)&&id>=0&&id<30){const r=s.stars?.[id];share('stage',entry,{chapter:Math.floor(id/6),stage:id%6,...(r?{stars:r.stars,tenths:Math.round(r.time*10)}:{})});}break;}
  case 'flight':if(s)share('flight',entry);break;
  case 'sky':{if(!s||!voyageUnlocked(s))break;const r=voyageRecord(s.sky);share('sky',entry,{best:r.best,total:r.total,treasures:r.treasures});break;}
  case 'voyage':{if(!s)break;const r=voyageRecord(s.sky),distance=Number(rest[0]);share('voyage',entry,{distance:Number.isSafeInteger(distance)?distance:0,best:r.best,total:r.total});break;}
  case 'treasure':{if(!s)break;const r=voyageRecord(s.sky);share('treasure',entry,{treasures:r.treasures,total:r.total,best:r.best});break;}
  case 'rank':{const rank=Number(rest[0]),row=lastBoard.find(e=>e.rank===rank&&e.uid===s?.ranking?.uid);if(!row)break;share('rank',entry,{rank:row.rank,distance:Number(row.distance)},{...s,flightName:row.name,...(row.design||{})});break;}
 }
}
function opening(){soundtrack.setScene('flight');showOpening(()=>{conversation(prologue,()=>{},{fadeIn:true});},{onTransition:timing=>{soundtrack.setScene(screen,timing);soundtrack.duck('story',true,timing.fadeIn);}});}
